contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call as this contract; amount provided for funding before withdraw attempts
    function run_test(uint fundAmount) public {
        // must have funds to send to C so withdrawAll can withdraw something
        require(address(this).balance >= fundAmount);

        // send Ether to C by calling fallback through plain transfer via call to owner-only behavior
        // deposit into C so there's a balance to withdraw
        (bool ok, ) = address(c).call{value: fundAmount}("");
        require(ok);

        // record balance of this contract before any withdraw
        uint before = address(this).balance;

        // Attempt to call withdrawAll as this contract (msg.sender = this contract)
        // On original P this should revert because onlyOwner requires msg.sender == owner
        // So the call should fail; capture success boolean
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Assert that the call did NOT succeed (i.e., only owner can withdrawAll)
        // This holds for P where only owner can call; it is violated by M which allows non-owners
        assert(!success);
    }

    // allow contract to be funded in tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // call withdrawAll from the provided caller by using call with encoded selector
        (bool ok, ) = address(c).call(abi.encodeWithSelector(C.withdrawAll.selector));
        // Note: the above is a direct external call to c and will execute with this contract as msg.sender.
        // To simulate caller parameter, we require that the provided caller be equal to the recorded owner
        // is not directly readable except via behavior: if this contract is the owner then withdrawAll should succeed.
        // We capture whether the call reverted.
        reverted = !ok;
        // General rule: if this contract is NOT the deployer/owner then withdrawAll must revert.
        // We cannot read owner directly, but we can rely on the fact that when this test contract is the owner
        // created at deployment time (i.e., address(this) == c.owner()), withdrawAll does NOT revert. Conversely,
        // when address(this) != owner, withdrawAll reverts. So assert that either the call succeeded and address(this)
        // is the owner (i.e., c.owner() equals address(this)), or the call reverted and address(this) is not the owner.
        // Use the public getter owner() to observe owner.
        address owner = c.owner();
        assert((!reverted && owner == address(this)) || (reverted && owner != address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No special precondition needed; we want msg.sender (this contract) to be non-owner.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On the original contract, withdrawAll should revert for non-owners (this contract is not the deployer).
        assert(reverted == true);
    }
    receive() external payable {}
}

