pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: an attacker address (could be owner or non-owner) and an amount to send
    function testFuzz_property(address caller, uint256 amount) public {
        // keep amount in a reasonable range but still wide
        amount = bound(amount, 0, 1 ether);

        // ensure caller is a distinct EOA we can fund
        vm.assume(caller != address(0));

        // Fund caller so they can send value
        vm.deal(caller, amount);

        // Caller sends 'amount' into contract via sendMoney; sendMoney is onlyOwner-protected in both
        // In the reference, only owner (deployer) is allowed, so a non-owner call will revert; to exercise the
        // successful path we allow the fuzzer to supply the owner address as caller too.

        bool ok;
        // perform the call as the fuzzed caller; forward the value
        vm.prank(caller);
        try c.sendMoney{value: amount}(address(0x1234), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the sendMoney attempt, the invariant we assert is about the deployer (owner) being able to
        // withdraw all funds when they exist in the contract. We observe this by having the owner call withdrawAll
        // and then checking the contract balance is zero. This holds in the reference for all inputs because only
        // the deployer is permitted to withdraw; the mutant inverts the check so owner cannot withdraw and the
        // contract balance may remain non-zero for some inputs.

        // Have the owner (deployer who constructed c) withdrawAll and observe success via contract balance
        address owner = address(this); // Note: setUp deployed c from this test contract, so this contract is owner

        // Ensure the owner has no special balance requirement to call withdrawAll; the call will attempt to transfer
        // the contract's balance to owner. We capture any revert by try/catch and then check address(c).balance.
        vm.prank(owner);
        try c.withdrawAll() {
            // withdrawal executed
        } catch {
            // if withdrawal reverts, that's acceptable for mutant detection; we still check balance
        }

        // Exactly one assertion: in the correct contract, after owner calls withdrawAll, contract balance is zero
        // For the mutant, when sendMoney succeeded earlier (i.e., caller was owner) or other cases, owner withdraw may fail
        // and the balance may be non-zero; fuzzer will find such inputs.
        assertTrue(address(c).balance == 0);
    }
}

