pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: attacker address and amount to send through sendMoney
    function testFuzz_property(address attacker, uint256 amount) public {
        // keep amount in a practical range and nonzero
        amount = bound(amount, 1, 1 ether);
        // the adversarial counterparty must be a contract that will withdraw in its fallback
        // deploy helper that will attempt to call withdrawAll on C when it receives funds
        Attacker a = new Attacker(address(c));

        // fund the owner (deployer) so owner can call sendMoney with value
        vm.deal(address(this), amount);

        // owner (deployer of C) calls sendMoney targeting the attacker contract, sending ether
        // c.sendMoney is onlyOwner so caller must be owner (this test contract is NOT the deployer of C)
        // we need to act as owner: the deployer of C was setUp() which did `new C()` executed by this contract,
        // so this contract is the owner. So vm.prank isn't needed; just call with value.
        c.sendMoney{value: amount}(address(a), amount);

        // At this point the attacker contract received the funds via low-level call in sendMoney.
        // Our Attacker's fallback will try to withdrawAll() from C (it is NOT the owner), which should revert in reference but succeed in mutant.
        // The Attacker attempted withdrawal during the low-level call; however sendMoney does not check the call return value,
        // and the fallback in C increments depositsCount (but not used here). We now check final balance and assert the invariant.

        // After the above, the correct contract must still have balance == amount, because onlyOwner prevents attacker from withdrawing during its fallback.
        // But mutant with inverted require will allow attacker to withdraw, leaving balance == 0 for some inputs.

        // Single assertion reading c's public surface: address(c).balance == amount must hold for the correct contract for ALL inputs
        // and the mutant will violate it for some inputs (when the attacker successfully withdraws in its fallback).
        assertTrue(address(c).balance == amount);
    }
}

// adversarial helper: on receiving funds, try to withdrawAll from C
contract Attacker {
    address payable target;
    constructor(address _target) { target = payable(_target); }
    fallback() external payable {
        // attempt to withdrawAll — onlyOwner should prevent this in the correct contract
        // use low-level call to avoid bubbling reverts here; we don't care if it reverts
        (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        // ignore ok
    }
}

