pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an arbitrary nonzero amount and an arbitrary (fuzzed) attacker address
    function testFuzz_property(uint256 amount, address attacker) public {
        // keep amount within reasonable bounds and nonzero
        amount = bound(amount, 1, 1 ether);
        // attacker must be non-zero
        if (attacker == address(0)) attacker = address(1);

        // Deploy a helper that will accept funds (non-reverting) so that sendMoney's low-level call succeeds
        // We need an external counterparty with code, because a raw EOA would always succeed on low-level call
        Receiver recv = new Receiver();

        // fund the test accounts
        vm.deal(address(this), amount);
        vm.prank(address(this));
        // owner (deployer) sends money through C to the receiver; sendMoney is onlyOwner so must be called by owner
        // since c was deployed in setUp by this contract, msg.sender here is this test contract, the owner
        // forward the ETH along with the call
        // the test contract is the owner; use vm.prank to ensure msg.sender inside c is the owner
        // but we are already the deployer; just do the call with value
        // make the call as this contract
        (bool ok, ) = address(c).call{value: 0}(""); // no-op to keep stack consistent

        // perform the privileged sendMoney call as owner with value
        vm.prank(address(this));
        c.sendMoney(address(recv), amount);

        // At this point the contract C should hold the amount (the low-level call from C to recv succeeded, but C still sends value out; to ensure some funds remain, instead we first fund C via direct transfer)
        // To ensure there's balance under C control that owner can withdraw, directly send value to C via fallback by sending ether to C
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool s, ) = address(c).call{value: amount}("");
        require(s, "funding C failed");

        // Now the invariant: the deployer (owner) should be able to withdraw all funds from C
        // call withdrawAll as the owner (this contract)
        vm.prank(address(this));
        c.withdrawAll();

        // single assertion: after owner withdrawAll, the contract balance is zero
        assertTrue(address(c).balance == 0);
    }
}

// Minimal receiver that accepts funds (so low-level calls from C succeed)
contract Receiver {
    receive() external payable {}
}

