pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: amount to send into C and an external counterparty address (we'll deploy a helper and pass its address)
    function testFuzz_property(uint256 amount, address counterparty) public {
        // Keep amount in a reasonable range (not too large to avoid overflow of vm.deal), but allow zero too
        amount = bound(amount, 0, 1 ether);

        // Deploy a simple external contract that accepts funds (EOAs fuzzed can't have code)
        Receiver r = new Receiver();

        // Ensure counterparty is not the zero address to keep domain wide but sensible
        vm.assume(counterparty != address(0));

        // Fund the owner (deployer) so it can send value to c via sendMoney
        address owner = address(this); // test contract is deployer of C in setUp()
        vm.deal(owner, amount);

        // From owner, call sendMoney to forward 'amount' to the receiver via the contract c
        vm.prank(owner);
        // sendMoney doesn't revert on call failures in reference; it performs a low-level call
        c.sendMoney(address(r), amount);

        // After sendMoney, the contract c may have balance (if the low-level call forwarded value to r, c's balance decreases).
        // To ensure there is some balance for withdrawAll to act on in the general rule, if amount==0 we still allow test to run
        // The general rule: owner can always call withdrawAll and leave address(c).balance == 0

        // Make sure the contract has some wei for the withdrawAll action. If c has zero balance currently, fund it directly from owner
        if (address(c).balance == 0 && amount > 0) {
            // deposit to contract by sending value directly
            vm.prank(owner);
            (bool ok, ) = address(c).call{value: amount}("x");
            // ignore ok; this is just to set up balance in admissible domain
        }

        // Now owner calls withdrawAll; reference contract should allow this and empty the balance
        vm.prank(owner);
        bool succeeded;
        try c.withdrawAll() {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // Exactly one assertion: on the reference C this must hold for all admissible inputs
        // The property: after owner calls withdrawAll, the contract balance is zero
        assertTrue(address(c).balance == 0);
    }
}

// Minimal receiver that accepts funds
contract Receiver {
    receive() external payable {}
}

